declare t clob;h varchar2(64);n number;begin dbms_lob.createtemporary(t,true);for r in(select text from user_source where name='RRL_TRADE_COMPOSITION_API'and type='PACKAGE BODY'order by line)loop dbms_lob.writeappend(t,length(replace(r.text,chr(13))),replace(r.text,chr(13)));end loop;while dbms_lob.substr(t,1,dbms_lob.getlength(t))=chr(10)loop dbms_lob.trim(t,dbms_lob.getlength(t)-1);end loop;h:=rawtohex(dbms_crypto.hash(t,dbms_crypto.hash_sh256));if h<>'5981EA6A9D7318ED29C09BEE8229B8822A6C51FDEDEABD72EB8FF94EDDEEB02A'then raise_application_error(-20999,'GUARD_HASH_MISMATCH');end if;select count(*)into n from user_objects where status='INVALID';if n<>0 then raise_application_error(-20999,'INVALID_OBJECTS');end if;dbms_lob.freetemporary(t);end;
/
